64	fn parse_arguments<T>(arguments: &str) -> Result<T, FunctionCallError>
65	where
66	    T: for<'de> Deserialize<'de>,
67	{
68	    serde_json::from_str(arguments).map_err(|err| {
69	        FunctionCallError::RespondToModel(format!("failed to parse function arguments: {err}"))
70	    })
71	}
72	
73	fn parse_arguments_with_base_path<T>(
74	    arguments: &str,
75	    base_path: &AbsolutePathBuf,
76	) -> Result<T, FunctionCallError>
77	where
78	    T: for<'de> Deserialize<'de>,
79	{
80	    let _guard = AbsolutePathBufGuard::new(base_path);
81	    parse_arguments(arguments)
82	}
