84	fn resolve_workdir_base_path(
85	    arguments: &str,
86	    default_cwd: &AbsolutePathBuf,
87	) -> Result<AbsolutePathBuf, FunctionCallError> {
88	    let arguments: Value = parse_arguments(arguments)?;
89	    Ok(arguments
90	        .get("workdir")
91	        .and_then(Value::as_str)
92	        .filter(|workdir| !workdir.is_empty())
93	        .map_or_else(|| default_cwd.clone(), |workdir| default_cwd.join(workdir)))
94	}
