96	fn resolve_tool_environment<'a>(
97	    turn: &'a TurnContext,
98	    environment_id: Option<&str>,
99	) -> Result<Option<&'a TurnEnvironment>, FunctionCallError> {
100	    environment_id.map_or_else(
101	        || Ok(turn.environments.primary()),
102	        |environment_id| {
103	            turn.environments
104	                .turn_environments
105	                .iter()
106	                .find(|environment| environment.environment_id == environment_id)
107	                .map(Some)
108	                .ok_or_else(|| {
109	                    FunctionCallError::RespondToModel(format!(
110	                        "unknown turn environment id `{environment_id}`"
111	                    ))
112	                })
113	        },
114	    )
115	}
