117	/// Validates feature/policy constraints for `with_additional_permissions` and
118	/// normalizes any path-based permissions. Errors if the request is invalid.
119	pub(crate) fn normalize_and_validate_additional_permissions(
120	    additional_permissions_allowed: bool,
121	    approval_policy: AskForApproval,
122	    sandbox_permissions: SandboxPermissions,
123	    additional_permissions: Option<AdditionalPermissionProfile>,
124	    permissions_preapproved: bool,
125	    _cwd: &Path,
126	) -> Result<Option<AdditionalPermissionProfile>, String> {
127	    let uses_additional_permissions = matches!(
128	        sandbox_permissions,
129	        SandboxPermissions::WithAdditionalPermissions
130	    );
131	
132	    if !permissions_preapproved
133	        && !additional_permissions_allowed
134	        && (uses_additional_permissions || additional_permissions.is_some())
135	    {
136	        return Err(
137	            "additional permissions are disabled; enable `features.exec_permission_approvals` before using `with_additional_permissions`"
138	                .to_string(),
139	        );
140	    }
141	
142	    if uses_additional_permissions {
143	        if !permissions_preapproved && !matches!(approval_policy, AskForApproval::OnRequest) {
144	            return Err(format!(
145	                "approval policy is {approval_policy:?}; reject command — you cannot request additional permissions unless the approval policy is OnRequest"
146	            ));
147	        }
148	        let Some(additional_permissions) = additional_permissions else {
149	            return Err(
150	                "missing `additional_permissions`; provide at least one of `network` or `file_system` when using `with_additional_permissions`"
151	                    .to_string(),
152	            );
153	        };
154	        let normalized = normalize_additional_permissions(additional_permissions)?;
155	        if normalized.is_empty() {
156	            return Err(
157	                "`additional_permissions` must include at least one requested permission in `network` or `file_system`"
158	                    .to_string(),
159	            );
160	        }
161	        return Ok(Some(normalized));
162	    }
163	
164	    if additional_permissions.is_some() {
165	        Err(
166	            "`additional_permissions` requires `sandbox_permissions` set to `with_additional_permissions`"
167	                .to_string(),
168	        )
169	    } else {
170	        Ok(None)
171	    }
172	}
